using System;using System.IO;using System.Threading.Tasks;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Threading;using WinBoard;
class CaptureStopSmoke {
 [STAThread]static void Main(){var app=new Application();var text=new TextBlock{FontSize=28,Foreground=Brushes.White,Margin=new Thickness(25)};var window=new Window{Title="Recording stop regression",Width=640,Height=360,Background=Brushes.DarkSlateBlue,Content=text};var clock=Stopwatch.StartNew();long previous=0,maxGap=0;int ticks=0;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};timer.Tick+=(s,e)=>{long now=clock.ElapsedMilliseconds;if(previous>0)maxGap=Math.Max(maxGap,now-previous);previous=now;text.Text="Live frame "+(++ticks);};window.Loaded+=async(s,e)=>{timer.Start();try{Directory.CreateDirectory("results");for(int cycle=0;cycle<3;cycle++){var session=new CaptureRecording();var complete=new TaskCompletionSource<string>();session.Completed+=(path,error)=>{if(error!=null)complete.TrySetException(new Exception(error));else complete.TrySetResult(path);};string file=Path.GetFullPath("results/stop-"+cycle+".mp4");session.Start(new CaptureTarget{Handle=new WindowInteropHelper(window).Handle},new CapturePreferences{SystemAudio=false,Microphone=false,Fps=15,Bitrate=4000000},file);await Task.Delay(1400);var elapsed=Stopwatch.StartNew();session.Stop();session.Stop();if(elapsed.ElapsedMilliseconds>150)throw new Exception("Stop blocked UI");if(await Task.WhenAny(complete.Task,Task.Delay(12000))!=complete.Task)throw new Exception("Stop/dispose completion timeout");string saved=await complete.Task;if(!File.Exists(saved)||File.Exists(Path.ChangeExtension(file,"recording.mp4")))throw new Exception("File finalization ordering");using(var stream=File.Open(saved,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){if(stream.Length<1000)throw new Exception("Video too small");}session.Dispose();session.Dispose();}if(ticks<50||maxGap>1000)throw new Exception("UI heartbeat stalled: "+maxGap);File.WriteAllText("results/pass.txt","PASS: 3 consecutive recording sessions; nonblocking double stop/dispose; finalized MP4 exclusively readable before completion; UI heartbeat max gap "+maxGap+"ms; audio/microphone disabled.");app.Shutdown();}catch(Exception ex){File.WriteAllText("error.txt",ex.ToString());app.Shutdown(1);}};app.Run(window);}
}
